'use strict';

const PDFDocument = require('pdfkit');
const { config, utils } = require('../engines');

const C = Object.freeze({
  pitch: '#075F48',
  pitchDark: '#054A38',
  pitchTint: '#E9F3EF',
  coal: '#06201A',
  ink: '#0C201A',
  ink2: '#41544A',
  ink3: '#71847A',
  ink4: '#93A39B',
  mist: '#EEF4F0',
  paper: '#FFFFFF',
  volt: '#D8F547',
  voltDark: '#9DAE2C',
  amber: '#B8860B',
  amberTint: '#FBF1DD',
  red: '#B3423A',
  line: '#D7DFDA'
});

const FONT = Object.freeze({
  sans: 'Helvetica',
  bold: 'Helvetica-Bold',
  display: 'Helvetica-Bold',
  mono: 'Courier',
  monoBold: 'Courier-Bold'
});

const PAGE = Object.freeze({
  width: 595.28,
  height: 841.89,
  left: 42,
  right: 42,
  top: 44,
  bottom: 46
});

const SCOUTLINK_LOGO = Buffer.from('', 'base64');

function clean(value) {
  return String(value == null ? '' : value)
    .replace(/[\u2012-\u2015]/g, '-')
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[\u201C\u201D]/g, '"')
    .replace(/\u2026/g, '...')
    .replace(/\u2022/g, '·')
    .replace(/\s+/g, ' ')
    .trim();
}

function number(value, fallback = null) {
  if (value === null || value === undefined || value === '') return fallback;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function clamp(value, min = 0, max = 100) {
  return Math.max(min, Math.min(max, number(value, 0)));
}

function rounded(value, places = 0) {
  const n = number(value, null);
  if (n === null) return null;
  const power = 10 ** places;
  return Math.round(n * power) / power;
}

function score100(value) {
  const n = number(value, null);
  if (n === null) return null;
  return rounded(n > 0 && n <= 10 ? n * 10 : n, 0);
}

function score10(value) {
  const n = number(value, null);
  if (n === null) return null;
  return rounded(n > 10 ? n / 10 : n, 1);
}

function playerName(player = {}) {
  return [player.first_name, player.last_name].filter(Boolean).join(' ') || 'Player';
}

function scoutName(scout = {}) {
  return [scout.first_name, scout.last_name].filter(Boolean).join(' ') || 'Scout';
}

function playerPosition(player = {}) {
  return player.specific_position || player.primary_position || player.position_group || 'Not recorded';
}

function formatDate(value, includeTime = false) {
  const date = value ? new Date(value) : new Date();
  if (Number.isNaN(date.getTime())) return clean(value);
  const options = includeTime
    ? { day:'2-digit', month:'short', year:'numeric', hour:'2-digit', minute:'2-digit' }
    : { day:'2-digit', month:'short', year:'numeric' };
  return date.toLocaleString('en-GB', options);
}

function monthShort(value) {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? '' : date.toLocaleDateString('en-GB', { month:'short' }).toUpperCase();
}

function dayNumber(value) {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? '' : String(date.getDate()).padStart(2, '0');
}

function relativeDate(value) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return '';
  const ms = Date.now() - date.getTime();
  const hours = Math.max(0, Math.floor(ms / 3600000));
  if (hours < 24) return hours <= 1 ? '1h ago' : `${hours}h ago`;
  const days = Math.floor(hours / 24);
  return days === 1 ? '1d ago' : `${days}d ago`;
}

function titleCase(value) {
  return clean(value).replace(/_/g, ' ').replace(/\b\w/g, letter => letter.toUpperCase());
}

function rangeText(range) {
  if (!range) return 'Not available';
  const min = number(range.minimum ?? range.min ?? range.low, null);
  const max = number(range.maximum ?? range.max ?? range.high, null);
  if (min === null || max === null) return clean(range.label || range);
  return `${Math.round(min)}-${Math.round(max)}`;
}

function reportCode(prefix, context) {
  const initials = scoutName(context.scout).split(/\s+/).filter(Boolean).slice(0,2).map(x => x[0]).join('').toUpperCase() || 'SL';
  const now = new Date();
  return `${prefix}-${initials}-${String(now.getMonth()+1).padStart(2,'0')}${String(now.getDate()).padStart(2,'0')}`;
}

function organisationName(context) {
  return context.team?.team_name || context.team?.club_name || context.scout?.club_name || 'ScoutLink Recruitment';
}

function setText(doc, font, size, color) {
  doc.font(font).fontSize(size).fillColor(color);
  return doc;
}

function rect(doc, x, y, w, h, fill, radius = 0, stroke = null, strokeWidth = 1) {
  if (radius) doc.roundedRect(x, y, w, h, radius);
  else doc.rect(x, y, w, h);
  if (fill) doc.fillColor(fill).fill();
  if (stroke) {
    if (radius) doc.roundedRect(x, y, w, h, radius);
    else doc.rect(x, y, w, h);
    doc.lineWidth(strokeWidth).strokeColor(stroke).stroke();
  }
}

function line(doc, x1, y1, x2, y2, color = C.line, width = 1) {
  doc.moveTo(x1, y1).lineTo(x2, y2).lineWidth(width).strokeColor(color).stroke();
}

function createDoc(info) {
  const doc = new PDFDocument({
    size: 'A4',
    margin: 0,
    compress: true,
    info: {
      Title: info.title,
      Author: `ScoutLink - ${info.organisation}`,
      Subject: info.subject,
      Creator: 'ScoutLink',
      Producer: 'ScoutLink PDF Export'
    }
  });
  doc.lineJoin('round').lineCap('round');
  return doc;
}

function collectPdf(doc) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    doc.on('data', chunk => chunks.push(chunk));
    doc.on('end', () => resolve(Buffer.concat(chunks)));
    doc.on('error', reject);
  });
}

function drawLogo(doc, x, y) {
  doc.image(SCOUTLINK_LOGO, x, y, { fit:[96, 31], align:'left', valign:'top' });
}

function baseState(doc, meta) {
  return {
    doc,
    y: PAGE.top,
    width: PAGE.width - PAGE.left - PAGE.right,
    pageNo: 1,
    kind: meta.kind,
    subtype: meta.subtype,
    organisation: meta.organisation,
    generatedBy: meta.generatedBy,
    report: meta.report
  };
}

function drawFooter(state) {
  const { doc } = state;
  const y = PAGE.height - 32;
  line(doc, PAGE.left, y - 10, PAGE.width - PAGE.right, y - 10, C.line, 0.8);
  setText(doc, FONT.mono, 6.5, C.ink3)
    .text(`Generated ${formatDate(new Date())} by ${state.generatedBy} · ${state.organisation}`, PAGE.left, y, { width:330 });
  setText(doc, FONT.mono, 6.5, C.ink3)
    .text('Confidential - for authorised recruitment use only', PAGE.width - PAGE.right - 215, y, { width:215, align:'right' });
}

function drawContinuationHeader(state) {
  const { doc } = state;
  drawLogo(doc, PAGE.left, 32);
  setText(doc, FONT.monoBold, 7.5, C.pitch)
    .text(`${state.kind.toUpperCase()} · ${state.subtype}`, PAGE.width - PAGE.right - 235, 37, { width:235, align:'right' });
  line(doc, PAGE.left, 62, PAGE.width - PAGE.right, 62, C.ink, 1.2);
  state.y = 82;
}

function addPage(state) {
  drawFooter(state);
  state.doc.addPage({ size:'A4', margin:0 });
  state.pageNo += 1;
  drawContinuationHeader(state);
}

function ensure(state, height) {
  if (state.y + height > PAGE.height - PAGE.bottom - 34) addPage(state);
}

function drawLetterhead(state) {
  const { doc } = state;
  drawLogo(doc, PAGE.left, state.y);
  setText(doc, FONT.monoBold, 7.8, C.pitch)
    .text(`ScoutLink · ${state.kind}`, PAGE.width - PAGE.right - 215, state.y + 2, { width:215, align:'right', characterSpacing:0.45 });
  setText(doc, FONT.bold, 12.5, C.ink)
    .text(state.subtype, PAGE.width - PAGE.right - 215, state.y + 16, { width:215, align:'right' });
  state.y += 43;
  line(doc, PAGE.left, state.y, PAGE.width - PAGE.right, state.y, C.ink, 1.5);
  state.y += 11;
}

function drawMetaRow(state, items) {
  const { doc } = state;
  const col = state.width / items.length;
  items.forEach((item, index) => {
    const x = PAGE.left + col * index;
    setText(doc, FONT.monoBold, 6.8, C.ink2).text(clean(item.label).toUpperCase(), x, state.y, { lineBreak:false });
    const lw = doc.widthOfString(clean(item.label).toUpperCase());
    setText(doc, FONT.mono, 6.8, C.ink3).text(` ${clean(item.value)}`, x + lw, state.y, { width:col-lw-3, lineBreak:false });
  });
  state.y += 25;
}

function drawChip(doc, text, x, y) {
  const label = clean(text).toUpperCase();
  setText(doc, FONT.monoBold, 6.2, C.pitch);
  const w = Math.max(48, doc.widthOfString(label) + 14);
  rect(doc, x, y, w, 17, C.mist, 8.5);
  doc.text(label, x + 7, y + 5, { lineBreak:false });
  return w;
}

function drawScoreTile(doc, x, y, label, value, width = 64) {
  rect(doc, x, y, width, 54, C.paper, 8, C.line, 1);
  setText(doc, FONT.display, 18, C.pitch).text(value == null ? '—' : clean(value), x, y + 8, { width, align:'center' });
  setText(doc, FONT.monoBold, 5.5, C.ink3).text(clean(label).toUpperCase(), x + 3, y + 35, { width:width-6, align:'center', characterSpacing:0.3 });
}

function drawSectionHeading(state, title, hint = '') {
  ensure(state, 28);
  const { doc } = state;
  setText(doc, FONT.bold, 10.5, C.ink).text(title, PAGE.left, state.y, { lineBreak:false });
  if (hint) setText(doc, FONT.mono, 6.3, C.ink3).text(hint, PAGE.left + 250, state.y + 1, { width:state.width-250, align:'right' });
  state.y += 15;
  line(doc, PAGE.left, state.y, PAGE.width - PAGE.right, state.y, C.ink, 0.8);
  state.y += 10;
}

function drawParagraph(state, value, options = {}) {
  const { doc } = state;
  const text = clean(value);
  if (!text) return;
  const size = options.size || 8.4;
  const width = options.width || state.width;
  const height = doc.heightOfString(text, { width, lineGap:2 });
  ensure(state, height + 6);
  setText(doc, options.bold ? FONT.bold : FONT.sans, size, options.color || C.ink2)
    .text(text, PAGE.left + (options.indent || 0), state.y, { width, lineGap:2 });
  state.y += height + 6;
}

function drawCallout(state, title, body, tone = 'pitch') {
  const { doc } = state;
  const bg = tone === 'amber' ? C.amberTint : C.pitchTint;
  const accent = tone === 'amber' ? C.amber : C.pitch;
  const width = state.width;
  const bodyText = clean(body);
  const titleText = clean(title);
  const bodyHeight = doc.heightOfString(bodyText, { width:width-34, lineGap:2 });
  const h = Math.max(45, bodyHeight + (titleText ? 28 : 20));
  ensure(state, h + 6);
  rect(doc, PAGE.left, state.y, width, h, bg, 7);
  rect(doc, PAGE.left, state.y, 3, h, accent, 0);
  if (titleText) setText(doc, FONT.bold, 8.2, C.ink).text(titleText, PAGE.left + 14, state.y + 10, { width:width-28 });
  setText(doc, FONT.sans, 7.8, tone === 'amber' ? '#7A5A0E' : C.pitchDark)
    .text(bodyText, PAGE.left + 14, state.y + (titleText ? 24 : 12), { width:width-28, lineGap:2 });
  state.y += h + 10;
}

function drawBarRow(state, label, value) {
  const { doc } = state;
  ensure(state, 19);
  const score = score100(value);
  const labelW = 135;
  const scoreW = 34;
  const trackX = PAGE.left + labelW + 8;
  const trackW = state.width - labelW - scoreW - 18;
  setText(doc, FONT.bold, 7.4, C.ink).text(clean(label), PAGE.left, state.y + 1, { width:labelW, lineBreak:false });
  rect(doc, trackX, state.y + 4, trackW, 5, C.mist, 3);
  if (score !== null) rect(doc, trackX, state.y + 4, trackW * clamp(score) / 100, 5, C.pitch, 3);
  setText(doc, FONT.monoBold, 6.8, C.ink).text(score === null ? '—' : `${Math.round(score)}/100`, trackX + trackW + 7, state.y + 1, { width:scoreW, align:'right' });
  state.y += 16;
}

function drawCategoryTiles(state, categories) {
  const { doc } = state;
  const gap = 8;
  const tileW = (state.width - gap * 3) / 4;
  ensure(state, 60);
  categories.forEach((item, index) => {
    const x = PAGE.left + index * (tileW + gap);
    rect(doc, x, state.y, tileW, 52, C.paper, 7, C.line, 0.9);
    setText(doc, FONT.monoBold, 5.8, C.ink3).text(clean(item.label).toUpperCase(), x+8, state.y+9, { width:tileW-16, characterSpacing:0.25 });
    setText(doc, FONT.display, 16, C.ink).text(item.value == null ? '—' : String(Math.round(item.value)), x+8, state.y+24, { width:tileW-16 });
  });
  state.y += 62;
}

function drawAttributeColumns(state, leftTitle, leftRows, rightTitle, rightRows) {
  const { doc } = state;
  const gap = 18;
  const colW = (state.width-gap)/2;
  const rowH = 18;
  const maxRows = Math.max(leftRows.length, rightRows.length);
  const total = 20 + maxRows * rowH;
  ensure(state, Math.min(total, 220));
  setText(doc, FONT.monoBold, 6.2, C.ink3).text(clean(leftTitle).toUpperCase(), PAGE.left, state.y, { width:colW });
  setText(doc, FONT.monoBold, 6.2, C.ink3).text(clean(rightTitle).toUpperCase(), PAGE.left+colW+gap, state.y, { width:colW });
  state.y += 13;

  for (let i=0; i<maxRows; i+=1) {
    if (state.y + rowH > PAGE.height-PAGE.bottom-40) {
      addPage(state);
      setText(doc, FONT.monoBold, 6.2, C.ink3).text(clean(leftTitle).toUpperCase(), PAGE.left, state.y, { width:colW });
      setText(doc, FONT.monoBold, 6.2, C.ink3).text(clean(rightTitle).toUpperCase(), PAGE.left+colW+gap, state.y, { width:colW });
      state.y += 13;
    }
    [[leftRows[i], PAGE.left],[rightRows[i], PAGE.left+colW+gap]].forEach(([row,x]) => {
      if (!row) return;
      line(doc, x, state.y+12, x+colW, state.y+12, C.line, 0.5);
      setText(doc, FONT.sans, 7, C.ink).text(clean(row.label), x, state.y+1, { width:colW-34, lineBreak:false, ellipsis:true });
      setText(doc, FONT.monoBold, 6.8, C.ink).text(row.value == null ? '—' : `${row.value}/10`, x+colW-35, state.y+1, { width:35, align:'right' });
    });
    state.y += rowH;
  }
  state.y += 8;
}

function drawGames(state, games) {
  const { doc } = state;
  (games || []).slice(0,3).forEach(match => {
    ensure(state, 31);
    const dateX = PAGE.left;
    setText(doc, FONT.display, 12, C.ink).text(dayNumber(match.match_date), dateX, state.y, { width:28, align:'center' });
    setText(doc, FONT.mono, 5.8, C.ink3).text(monthShort(match.match_date), dateX, state.y+15, { width:28, align:'center' });
    const opponent = match.opponent_name || match.opponent || 'Opponent';
    setText(doc, FONT.bold, 7.7, C.ink).text(`vs ${clean(opponent)}`, PAGE.left+40, state.y+6, { width:300, lineBreak:false, ellipsis:true });
    const rating = score10(match.performance_score ?? match.overall_rating ?? match.rating);
    setText(doc, FONT.monoBold, 6.8, C.pitch).text(rating === null ? 'Recorded' : `${rating} contextual`, PAGE.width-PAGE.right-105, state.y+6, { width:105, align:'right' });
    state.y += 27;
    line(doc, PAGE.left, state.y, PAGE.width-PAGE.right, state.y, C.line, 0.6);
    state.y += 4;
  });
}

function drawNotes(state, notes) {
  const { doc } = state;
  if (!(notes || []).length) {
    drawParagraph(state, 'No visible-to-team notes have been recorded for this player.');
    return;
  }
  notes.forEach(note => {
    const content = clean(note.content || note.body || note.comment);
    const h = Math.max(34, doc.heightOfString(content, { width:state.width-8, lineGap:2 }) + 22);
    ensure(state, h);
    setText(doc, FONT.bold, 7.7, C.ink).text(clean(note.authorName || 'Scout'), PAGE.left, state.y, { lineBreak:false });
    const nameW = doc.widthOfString(clean(note.authorName || 'Scout'));
    setText(doc, FONT.mono, 6, C.ink3).text(relativeDate(note.created_at), PAGE.left+nameW+7, state.y+1, { lineBreak:false });
    setText(doc, FONT.sans, 7.3, C.ink2).text(content, PAGE.left, state.y+13, { width:state.width, lineGap:2 });
    state.y += h-4;
    line(doc, PAGE.left, state.y, PAGE.width-PAGE.right, state.y, C.line, 0.6);
    state.y += 6;
  });
}

function drawListRows(state, rows, emptyText = 'No additional evidence is available.') {
  const { doc } = state;
  if (!(rows || []).length) {
    drawParagraph(state, emptyText);
    return;
  }
  rows.forEach(row => {
    const title = clean(row.title || row.label || 'Evidence');
    const body = clean(row.body || row.note || row.content || '');
    const h = Math.max(31, doc.heightOfString(body, { width:state.width-8, lineGap:2 }) + 22);
    ensure(state, h);
    setText(doc, FONT.bold, 7.7, C.ink).text(title, PAGE.left, state.y, { width:state.width });
    setText(doc, FONT.sans, 7.3, C.ink2).text(body, PAGE.left, state.y+13, { width:state.width, lineGap:2 });
    state.y += h-4;
    line(doc, PAGE.left, state.y, PAGE.width-PAGE.right, state.y, C.line, 0.6);
    state.y += 6;
  });
}

function currentAttributeRows(bundle) {
  const player = bundle.player;
  const group = utils.getPositionGroup(player);
  const groupKey = String(group || '').toLowerCase();
  const generalKeys = group === 'Goalkeeper' ? [] : (config.GENERAL_ATTRIBUTES || []);
  const positionKeys = config.ATTRIBUTE_GROUPS?.[groupKey] || [];
  const generalRatings = utils.collectRatings(player, generalKeys);
  const positionalRatings = utils.collectRatings(player, positionKeys);
  const toRows = (keys, ratings) => keys.map(key => ({
    key,
    label: config.ATTRIBUTE_DEFINITIONS?.[key]?.label || titleCase(key),
    value: score10(ratings?.[key])
  })).filter(row => row.value !== null);
  return { group, general:toRows(generalKeys, generalRatings), positional:toRows(positionKeys, positionalRatings), all:[...toRows(generalKeys,generalRatings),...toRows(positionKeys,positionalRatings)] };
}

function categoryScores(bundle) {
  const rows = currentAttributeRows(bundle).all;
  const categoryMap = {
    technical: { label:'Technical', values:[] },
    tacticalCognitive: { label:'Tactical', values:[] },
    physical: { label:'Physical', values:[] },
    mentalDevelopmental: { label:'Mental', values:[] }
  };
  rows.forEach(row => {
    const category = config.ATTRIBUTE_DEFINITIONS?.[row.key]?.category;
    if (categoryMap[category]) categoryMap[category].values.push(row.value * 10);
  });
  return Object.values(categoryMap).map(item => ({
    label:item.label,
    value:item.values.length ? Math.round(item.values.reduce((a,b)=>a+b,0)/item.values.length) : null
  }));
}

function compatibilityModel(bundle) {
  const a = bundle.analysis || {};
  const c = a.compatibility || a.compatibilityBreakdown || {};
  const score = score100(c.conservativeScore ?? c.finalScore ?? a.compatibilityScore ?? bundle.player.compatibility_score);
  const likely = c.likelyRange || a.evidenceConfidence?.likelyRange || null;
  const setup = c.setup || {};
  const components = [
    ['Formation position fit', c.formationPositionFit],
    ['Required role fit', c.roleFit],
    ['Playing style fit', c.tacticalStyleFit],
    ['Team need fit', c.needFit ?? c.teamNeedFit],
    ['Development pathway', c.developmentPathwayFit]
  ];
  const strongest = components.filter(x => number(x[1],null)!==null).sort((x,y)=>number(y[1])-number(x[1]))[0];
  const weakest = components.filter(x => number(x[1],null)!==null).sort((x,y)=>number(x[1])-number(y[1]))[0];
  const confidence = c.evidenceConfidence?.label || a.evidenceConfidence?.label || bundle.evidenceLabel || 'Recorded evidence';
  const why = c.explanation || (score === null
    ? 'Compatibility is not available for the current Scout setup.'
    : `${strongest ? strongest[0] : 'The strongest component'} is the clearest fit${strongest ? ` (${Math.round(score100(strongest[1]))}/100)` : ''}, while ${weakest ? weakest[0].toLowerCase() : 'the lowest component'} is the main constraint${weakest ? ` (${Math.round(score100(weakest[1]))}/100)` : ''}. Evidence confidence (${confidence}) controls the likely range - it does not add compatibility points.`);
  return { score, likely, components, why, setup };
}

function valueModel(bundle) {
  const analysis = bundle.analysis || {};
  const value = analysis.valueAnalysis || bundle.player.value_analysis || {};
  const index = score100(analysis.footballValueIndex ?? value.footballValueIndex ?? bundle.player.football_value_index);
  const range = value.likelyRange || value.indexRange || value.footballValueIndexRange || analysis.footballValueIndexRange || null;
  const currency = value.valueFormatted || value.currencyValueFormatted || null;
  const status = value.currencyEstimateStatus || (currency ? 'Anchored estimate' : 'Not estimated');
  const explanation = value.explanation || 'The Football Value Index summarises current football ability, development outlook, role usefulness and the direction of the evidence without turning the score into an unverified transfer-fee estimate.';
  return { index, range, currency, status, explanation };
}

function drawPlayerProfile(doc, context, bundle) {
  const state = baseState(doc, {
    kind:'Player Export', subtype:'Player Profile',
    organisation:organisationName(context),
    generatedBy:scoutName(context.scout), report:reportCode('PP', context)
  });
  drawLetterhead(state);
  drawMetaRow(state, [
    {label:'Exported',value:formatDate(new Date(), true)},
    {label:'Organisation',value:state.organisation},
    {label:'Report',value:state.report}
  ]);

  const p = bundle.player;
  const compat = compatibilityModel(bundle);
  const val = valueModel(bundle);
  ensure(state, 82);
  const heroY = state.y;
  setText(doc, FONT.bold, 17, C.ink).text(playerName(p), PAGE.left, heroY, { width:290 });
  const detail = [playerPosition(p), p.age_group, p.team_name, p.foot ? `${p.foot} foot` : '', p.availability || ''].filter(Boolean).join(' · ');
  setText(doc, FONT.sans, 8.2, C.ink2).text(detail, PAGE.left, heroY+24, { width:300 });
  let chipX = PAGE.left;
  if (bundle.pipeline) {
    chipX += drawChip(doc, 'In pipeline', chipX, heroY+47) + 6;
    if (bundle.pipeline.stage) drawChip(doc, titleCase(bundle.pipeline.stage), chipX, heroY+47);
  }
  const tileW = 62, gap=6;
  const tileX = PAGE.width-PAGE.right-(tileW*3+gap*2);
  drawScoreTile(doc,tileX,heroY,'Overall',score100(p.overall_rating),tileW);
  drawScoreTile(doc,tileX+tileW+gap,heroY,'Compatibility',compat.score,tileW);
  drawScoreTile(doc,tileX+(tileW+gap)*2,heroY,'Value index',val.index,tileW);
  state.y += 75;
  line(doc,PAGE.left,state.y,PAGE.width-PAGE.right,state.y,C.line,0.8);
  state.y += 18;

  drawSectionHeading(state,'Compatibility breakdown','Conservative team-specific score');
  ensure(state, 104);
  const scoreBoxY=state.y;
  rect(doc,PAGE.left,scoreBoxY,100,70,C.paper,8,C.line,1);
  setText(doc,FONT.display,25,C.pitch).text(compat.score===null?'—':String(Math.round(compat.score)),PAGE.left,scoreBoxY+11,{width:100,align:'center'});
  setText(doc,FONT.mono,5.8,C.ink3).text(compat.likely?`LIKELY RANGE ${rangeText(compat.likely)}`:'LIKELY RANGE -',PAGE.left+6,scoreBoxY+47,{width:88,align:'center'});
  const barLeft=PAGE.left+118;
  compat.components.forEach(([label,value],idx)=>{
    const rowY=scoreBoxY+idx*14;
    const score=score100(value);
    setText(doc,FONT.bold,6.6,C.ink).text(label,barLeft,rowY+1,{width:120,lineBreak:false});
    const trackX=barLeft+125, trackW=168;
    rect(doc,trackX,rowY+3,trackW,5,C.mist,3);
    if(score!==null) rect(doc,trackX,rowY+3,trackW*clamp(score)/100,5,C.pitch,3);
    setText(doc,FONT.monoBold,6.2,C.ink).text(score===null?'—':`${Math.round(score)}/100`,trackX+trackW+6,rowY,{width:44,align:'right'});
  });
  state.y += 82;
  drawCallout(state, compat.score===null?'Compatibility':`Why ${Math.round(compat.score)}?`, compat.why);

  const attr = currentAttributeRows(bundle);
  drawSectionHeading(state,'Attribute profile',`${attr.group || 'Position'} · recorded attributes`);
  drawCategoryTiles(state,categoryScores(bundle));
  if (attr.group === 'Goalkeeper') {
    const midpoint=Math.ceil(attr.positional.length/2);
    drawAttributeColumns(state,'Goalkeeper attributes',attr.positional.slice(0,midpoint),'Goalkeeper attributes',attr.positional.slice(midpoint));
  } else {
    drawAttributeColumns(state,'General attributes',attr.general,`${attr.group} attributes`,attr.positional);
  }

  drawSectionHeading(state,'Financial Value Index','Index first · currency only when verified');
  ensure(state,80);
  rect(doc,PAGE.left,state.y,90,65,C.paper,8,C.line,1);
  setText(doc,FONT.display,24,C.pitch).text(val.index===null?'—':String(Math.round(val.index)),PAGE.left,state.y+11,{width:90,align:'center'});
  setText(doc,FONT.mono,6,C.ink3).text('/100',PAGE.left,state.y+45,{width:90,align:'center'});
  setText(doc,FONT.sans,7.5,C.ink2).text(clean(val.explanation),PAGE.left+108,state.y+2,{width:state.width-108,lineGap:2});
  const currencyText = val.currency && val.status !== 'Not estimated' ? val.currency : 'Not estimated';
  setText(doc,FONT.bold,7.4,C.ink).text(`Current currency estimate: ${currencyText}`,PAGE.left+108,state.y+48,{width:state.width-108});
  state.y += 78;

  drawSectionHeading(state,'Recent games');
  const past = (bundle.matches || []).filter(match => !match.match_date || new Date(match.match_date).getTime() <= Date.now()).slice(0,3);
  drawGames(state,past);

  drawSectionHeading(state,'Team notes','Visible-to-team notes only');
  drawNotes(state,(bundle.teamNotes||[]).slice(0,12));

  drawFooter(state);
}

function predictionTitle(type, player) {
  const name=playerName(player);
  if (/Attribute Development/i.test(type)) return `${name} · Development Outlook`;
  if (/Position Fit/i.test(type)) return `${name} · Position Fit Review`;
  if (/Match Scenario/i.test(type)) return `${name} · Match Scenario Review`;
  if (/ROI/i.test(type)) return `${name} · Football Value Outlook`;
  return `${name} · Prediction Report`;
}

function predictionIntro(type) {
  if (/Attribute Development/i.test(type)) return 'A bounded five-season development scenario built from the current overall assessment, age phase, selected development plan and recorded evidence. This is decision support, not a promise of future performance.';
  if (/Position Fit/i.test(type)) return 'A position-specific projection using the V4 current-position, role and evidence model. The target is compared against supported current positions without inventing missing evidence.';
  if (/Match Scenario/i.test(type)) return 'A bounded tactical scenario estimate using the player’s recorded attributes and contextual evidence. The likely range matters more than a single point score.';
  if (/ROI/i.test(type)) return 'An evidence-led Football Value Index projection. Currency and ROI are only shown where verified market anchors exist.';
  return 'ScoutLink decision-support prediction generated from the current V4 scoring model.';
}

function drawKpis(state, kpis) {
  const { doc }=state;
  const gap=8, tileW=(state.width-gap*3)/4, h=70;
  ensure(state,h+10);
  kpis.slice(0,4).forEach((kpi,index)=>{
    const x=PAGE.left+index*(tileW+gap);
    rect(doc,x,state.y,tileW,h,C.paper,8,C.line,0.9);
    setText(doc,FONT.monoBold,5.8,C.ink3).text(clean(kpi.label).toUpperCase(),x+9,state.y+9,{width:tileW-18,characterSpacing:0.25});
    setText(doc,FONT.display,15,C.ink).text(clean(kpi.value ?? '—'),x+9,state.y+26,{width:tileW-18});
    setText(doc,FONT.sans,5.9,C.ink3).text(clean(kpi.small||''),x+9,state.y+49,{width:tileW-18,lineGap:1});
  });
  state.y += h+14;
}

function drawChart(state, points) {
  const { doc }=state;
  const cleaned=(points||[]).map(p=>({label:clean(p.label),value:number(p.value,null)}));
  if(!cleaned.length)return;
  const h=110, gap=8, barW=(state.width-gap*(cleaned.length-1))/cleaned.length;
  ensure(state,h+20);
  const baseY=state.y+h-22;
  line(doc,PAGE.left,baseY,PAGE.width-PAGE.right,baseY,C.line,0.7);
  cleaned.forEach((point,index)=>{
    const x=PAGE.left+index*(barW+gap);
    const displayed=point.value===null?null:clamp(Math.round(point.value));
    const fillH=displayed===null?4:Math.max(4,72*displayed/100);
    if(displayed!==null)rect(doc,x+2,baseY-fillH,barW-4,fillH,C.pitch,4);
    setText(doc,FONT.monoBold,6.2,C.ink).text(displayed===null?'—':String(displayed),x,baseY-fillH-12,{width:barW,align:'center'});
    setText(doc,FONT.mono,5.8,C.ink3).text(point.label,x,baseY+6,{width:barW,align:'center'});
  });
  state.y += h+4;
}

function drawSimpleTable(state, columns, rows) {
  const { doc }=state;
  if(!(rows||[]).length){drawParagraph(state,'No additional scored evidence is available.');return;}
  const widths = columns.map(col=>col.width);
  const total=widths.reduce((a,b)=>a+b,0);
  const scale=state.width/total;
  const scaled=widths.map(w=>w*scale);
  const headerH=20;
  ensure(state,headerH+26);
  rect(doc,PAGE.left,state.y,state.width,headerH,C.mist,0);
  let x=PAGE.left;
  columns.forEach((col,i)=>{
    setText(doc,FONT.monoBold,5.7,C.ink3).text(clean(col.label).toUpperCase(),x+5,state.y+6,{width:scaled[i]-10});
    x+=scaled[i];
  });
  state.y += headerH;
  rows.forEach(row=>{
    const lineHeights=row.map((cell,i)=>doc.heightOfString(clean(cell),{width:scaled[i]-10,lineGap:1}));
    const h=Math.max(24,Math.max(...lineHeights)+10);
    ensure(state,h);
    let cx=PAGE.left;
    row.forEach((cell,i)=>{
      setText(doc,i===0?FONT.bold:FONT.sans,6.8,C.ink).text(clean(cell),cx+5,state.y+6,{width:scaled[i]-10,lineGap:1});
      cx+=scaled[i];
    });
    state.y += h;
    line(doc,PAGE.left,state.y,PAGE.width-PAGE.right,state.y,C.line,0.5);
  });
  state.y += 8;
}

function predictionKpis(type,result,bundle) {
  if(/Attribute Development/i.test(type)) return [
    {label:'Current overall',value:Math.round(number(result.currentOverall,bundle.player.overall_rating||0)),small:'Current position-specific ability'},
    {label:'Projected overall',value:Math.round(number(result.potentialOverall,result.seasons?.at(-1)?.overall)),small:'Bounded five-season estimate'},
    {label:'Likely range',value:rangeText(result.likelyRange),small:'Use the range, not just the point'},
    {label:'Trajectory',value:result.predictionDetails?.trajectory||result.trajectory||'Review',small:'Recent contextual evidence'}
  ];
  if(/Position Fit/i.test(type)) return [
    {label:'Best current position',value:result.bestCurrentPosition||'—',small:'Current supported position'},
    {label:'Target position',value:result.targetPosition||'—',small:'Selected conversion target'},
    {label:'Gap vs best',value:result.targetGapVsBest==null?'—':`${result.targetGapVsBest>0?'+':''}${rounded(result.targetGapVsBest,1)}`,small:'Target relative to current best'},
    {label:'Verdict',value:result.targetVerdict||'Review',small:'Conversion status'}
  ];
  if(/Match Scenario/i.test(type)) return [
    {label:'Scenario score',value:result.scenarioScore==null?'—':Math.round(result.scenarioScore),small:result.scenario||'Selected tactical scenario'},
    {label:'Likely range',value:rangeText(result.likelyRange),small:'Evidence-bounded range'},
    {label:'Current risk',value:result.risk||'Review',small:'Scenario-specific risk'},
    {label:'Recommendation',value:result.recommendation||'Review',small:'Recruitment guidance'}
  ];
  const val=result.currentTransferValue||{};
  const projection=result.projection||[];
  return [
    {label:'Football Value Index',value:val.footballValueIndex==null?'—':Math.round(val.footballValueIndex),small:'Index first'},
    {label:'Likely index range',value:rangeText(result.valueAnalysis?.likelyRange||result.valueAnalysis?.indexRange),small:'Evidence-bounded range'},
    {label:'Five-season index',value:projection.at(-1)?.footballValueIndex==null?'—':Math.round(projection.at(-1).footballValueIndex),small:'Bounded projection'},
    {label:'Currency value',value:val.formatted||'Not estimated',small:'Only with verified anchors'}
  ];
}

function drawPredictionSpecific(state,type,result,bundle) {
  if(/Attribute Development/i.test(type)) {
    drawSectionHeading(state,'Projected overall by season');
    const points=[{label:'Current',value:result.currentOverall},...(result.seasons||[]).map(s=>({label:`Y${s.year}`,value:s.overall}))];
    drawChart(state,points);
    drawSectionHeading(state,'Attribute movement','1-10 coach scale');
    const effects=(result.attributeEffects||[]).slice().sort((a,b)=>Math.abs(number(b.deltaFiveYear,0))-Math.abs(number(a.deltaFiveYear,0))).slice(0,8);
    const seasons=result.seasons||[];
    const yr3=seasons.find(s=>Number(s.year)===3)||seasons[Math.min(2,seasons.length-1)]||{};
    const yr5=seasons.find(s=>Number(s.year)===5)||seasons.at(-1)||{};
    const current=result.currentAttributes||{};
    const rows=effects.map(effect=>{
      const key=Object.keys(result.attributeEffectsByKey||{}).find(k=>(result.attributeEffectsByKey[k]?.attribute||k)===effect.attribute) || effect.key;
      return [effect.attribute||titleCase(key), current[key]??'—', yr3.attributes?.[key]??'—', yr5.attributes?.[key]??'—', effect.deltaFiveYear==null?'—':`${effect.deltaFiveYear>0?'+':''}${effect.deltaFiveYear}`];
    });
    drawSimpleTable(state,[{label:'Attribute',width:190},{label:'Current',width:70},{label:'Yr 3',width:70},{label:'Yr 5',width:70},{label:'Change',width:70}],rows);
    return;
  }
  if(/Position Fit/i.test(type)) {
    drawSectionHeading(state,'Position rating comparison','Supported positions');
    Object.entries(result.positionRatings||{}).sort((a,b)=>number(b[1])-number(a[1])).slice(0,10).forEach(([position,value])=>drawBarRow(state,position,value));
    drawSectionHeading(state,`Top ${result.targetPosition||'target'} role fits`,'Role evidence');
    const roles=(result.topRoles||[]).map(role=>({title:`${role.role||role.position||'Role'} · ${role.score==null?'—':Math.round(role.score)}`,body:role.status||'Role fit generated from the recorded position attributes.'}));
    drawListRows(state,roles,`No ${result.targetPosition||'target-position'} role evidence is available yet.`);
    drawSectionHeading(state,'Conversion evidence','Why the target works / where it strains');
    const candidates=(result.conversionCandidates||[]).slice(0,8).map(item=>[item.position||item.targetPosition||'Position',item.projectedRating??item.score??'—',item.reason||item.status||'Supported conversion evidence']);
    drawSimpleTable(state,[{label:'Requirement',width:110},{label:'Score',width:70},{label:'Interpretation',width:300}],candidates);
    return;
  }
  if(/Match Scenario/i.test(type)) {
    drawSectionHeading(state,'Scenario evidence',result.scenario||'Selected scenario');
    const evidence=(result.evidence||[]).map(item=>[item.attribute||item.label||'Metric',item.score??item.value??'—',item.note||item.reason||'Recorded evidence']);
    drawSimpleTable(state,[{label:'Requirement',width:150},{label:'Score',width:60},{label:'Interpretation',width:270}],evidence);
    drawSectionHeading(state,'Predicted behaviour');
    drawCallout(state,'Recruitment implication',result.predictedBehaviour||result.summary||'Review the scenario alongside live evidence.');
    drawSectionHeading(state,'Live proof checklist');
    drawListRows(state,(result.liveProof||[]).map((item,index)=>({title:`Check ${index+1}`,body:item})),'No live-proof checklist was generated.');
    return;
  }
  drawSectionHeading(state,'Football Value Index projection');
  const projection=result.projection||[];
  const current=result.currentTransferValue?.footballValueIndex;
  drawChart(state,[{label:'Current',value:current},...projection.map(row=>({label:`Y${row.year||''}`,value:row.footballValueIndex}))]);
  drawSectionHeading(state,'Value drivers');
  (result.valueDrivers||[]).slice(0,8).forEach(driver=>drawBarRow(state,driver.label||driver.name||'Value driver',driver.score??driver.value));
  drawSectionHeading(state,'Financial scenario readiness');
  drawCallout(state,'Recruitment implication',result.recommendation||result.suitability||'Use the Football Value Index until verified financial anchors exist.');
  drawSectionHeading(state,'Risk & governance');
  drawListRows(state,(result.risks||[]).slice(0,8).map(risk=>({title:risk.label||risk.level||'Model limitation',body:risk.note||risk.warning||risk})),'No additional model risks were generated.');
}

function drawPrediction(doc, context, bundle, log) {
  const result=log.result||{};
  const type=log.prediction_type||result.type||'Prediction';
  const prefix=/Attribute Development/i.test(type)?'AD':/Position Fit/i.test(type)?'PF':/Match Scenario/i.test(type)?'MS':'ROI';
  const state=baseState(doc,{
    kind:'Intelligence Report',subtype:type,
    organisation:organisationName(context),generatedBy:scoutName(context.scout),report:reportCode(prefix,context)
  });
  drawLetterhead(state);
  drawMetaRow(state,[
    {label:'Generated',value:formatDate(log.run_at||new Date())},
    {label:'Report',value:state.report},
    {label:'Scoring',value:'v4.0.0'}
  ]);

  ensure(state,90);
  drawChip(doc,`ScoutLink Intelligence Report · ${type}`,PAGE.left,state.y);
  state.y += 27;
  setText(doc,FONT.bold,17,C.ink).text(predictionTitle(type,bundle.player),PAGE.left,state.y,{width:state.width});
  state.y += 25;
  drawParagraph(state,predictionIntro(type),{size:8.2,width:state.width-20});
  drawKpis(state,predictionKpis(type,result,bundle));

  drawSectionHeading(state,'Executive summary');
  drawParagraph(state,result.summary||(result.paragraphs||[])[0]||'Prediction completed.');
  const implication=result.recommendation||result.tacticalNote||(result.paragraphs||[])[1]||'Use this result alongside live observation and the underlying evidence.';
  drawCallout(state,'Recruitment implication',implication);

  drawPredictionSpecific(state,type,result,bundle);

  drawSectionHeading(state,'Evidence, confidence & next checks');
  const confidence=result.confidence?.label||result.confidence||bundle.evidenceLabel||'Recorded evidence';
  const evidenceRows=[
    {title:`Confidence: ${confidence}`,body:result.confidence?.note||'The likely range is more important than the exact point estimate.'},
    {title:'Live check',body:result.tacticalNote||(result.liveProof||[])[0]||'Verify the highest-impact model assumption in live observation.'},
    {title:'Model limitation',body:result.disclaimer||'ScoutLink predictions are bounded decision-support estimates, not guarantees.'}
  ];
  drawListRows(state,evidenceRows);
  drawCallout(state,'',result.disclaimer||'This is a bounded decision-support scenario, not a promise of future performance.', 'amber');
  drawFooter(state);
}

async function renderPlayerProfilePdf({ context, bundle }) {
  const doc=createDoc({title:`${playerName(bundle.player)} - Player Profile`,organisation:organisationName(context),subject:'ScoutLink Player Profile'});
  const promise=collectPdf(doc);
  drawPlayerProfile(doc,context,bundle);
  doc.end();
  return promise;
}

async function renderPredictionPdf({ context, bundle, log }) {
  const type=log.prediction_type||log.result?.type||'Prediction';
  const doc=createDoc({title:`${playerName(bundle.player)} - ${type}`,organisation:organisationName(context),subject:`ScoutLink ${type}`});
  const promise=collectPdf(doc);
  drawPrediction(doc,context,bundle,log);
  doc.end();
  return promise;
}

module.exports = {
  renderPlayerProfilePdf,
  renderPredictionPdf,
  helpers: { compatibilityModel, currentAttributeRows, categoryScores, valueModel }
};
